(n, m) = map(int, input().split())
(p, s) = ([], {})
x = 0
for i in range(n):
	for (j, q) in enumerate(input()):
		if q != '#':
			continue
		s[i, j] = x
		p.append([])
		if (i, j - 1) in s:
			p[x] += [x - 1]
			p[x - 1] += [x]
		if (i - 1, j) in s:
			y = s[i - 1, j]
			p[x] += [y]
			p[y] += [x]
		x += 1
k = len(p)
if k < 3:
	print(-1)
	exit()
for j in range(k):
	d = [1] * k
	d[j] = 0
	s = [p[j][0]]
	while s:
		j = s.pop()
		if not d[j]:
			continue
		d[j] = 0
		for i in p[j]:
			if d[i]:
				s.append(i)
	if 1 in d:
		print(1)
		break
else:
	print(2)
